<section class="panel"><h2>Deine Gutscheine</h2><?php $entries=all('SELECT * FROM shop_coupons ORDER BY id DESC');if(!$entries):empty_state('bolt','Noch keine Gutscheine','Erstelle einen festen, prozentualen oder bedingten Gutschein.');else: ?><div class="table-scroll"><table><thead><tr><th>Code / Bezeichnung</th><th>Rabatt</th><th>Gültigkeit</th><th>Einlösungen</th><th></th></tr></thead><tbody><?php foreach($entries as $c):$r=json_decode($c['rules'],true);$used=(int)query("SELECT COUNT(*) FROM shop_coupon_uses WHERE coupon_id=? AND state='used'",[$c['id']])->fetchColumn();$held=(int)query("SELECT COUNT(*) FROM shop_coupon_uses WHERE coupon_id=? AND state='reserved'",[$c['id']])->fetchColumn(); ?><tr><td><strong><?= e($c['code']) ?></strong><small><?= e($c['name']) ?></small></td><td><?= $c['kind']==='bundle'?'Domain / Webspace zum VPS':($c['kind']==='fixed'?money($r['fixed_net_cents']).' netto':number_format($r['percent_bps']/100,2,',','.').' %') ?><small><?= $r['duration']==='recurring'?'Laufend':'Erster Zeitraum' ?><?= $r['test_only']?' · Persönlicher Test':'' ?></small></td><td><?= $c['active']?'Aktiv':'Deaktiviert' ?><small><?= $r['customer_id']?'Nur Kunde #'.(int)$r['customer_id']:'Alle passenden Kunden' ?></small></td><td><?= $used ?> eingelöst<small><?= $held ?> reserviert</small></td><td><a class="text-link" href="/admin/gutscheine?id=<?= (int)$c['id'] ?>">Bearbeiten</a></td></tr><?php endforeach ?></tbody></table></div><?php endif ?></section>
